using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;

public static class A01Inspector
{
    public static string RunStartedUtc;
    public static string RunReturnedUtc;
    public static string ManagerErrors;

    public sealed class Node
    {
        public string path;
        public string methods;
        public string[] variables;
        public object data;
        public int[] dimensions;
        public string timestamp;
        public string data_entry;
        public string data_source;
        public string evaluation_error;
        public Dictionary<string, object> analysis_settings;
    }

    private static void Visit(GENESYS.IItem item, string path, int depth, List<Node> nodes)
    {
        if (path.EndsWith("/Eqns"))
        {
            depth = 3;
        }
        if ((path.Contains("/Sch1/PartList/") || path.Contains("/Example/PartList/")) && path.Split('/').Length == 5)
        {
            depth = 2;
        }
        if (nodes.Count >= 12000)
        {
            throw new InvalidOperationException("Reference inspection node limit exceeded");
        }
        var variables = new string[item.GetVarCount()];
        for (int index = 0; index < variables.Length; ++index)
        {
            variables[index] = item.GetVarName(index) + ":" + item.GetVarType(index);
        }
        var node = new Node { path = path, methods = item.GetMethodList(), variables = variables };
        for (int index = 0; index < variables.Length; ++index)
        {
            string name = item.GetVarName(index);
            if ((path.EndsWith("/System1") || path.EndsWith("/System2")) &&
                (name == "CoherentIM" || name == "ShowTotals" || name == "CalcNoise" ||
                 name == "CalcHarmonics" || name == "CalcIntermods" || name == "PhaseNoise" ||
                 name == "UseSourcePts" || name == "NeedRun" || name == "AutoCalc"))
            {
                if (node.analysis_settings == null)
                {
                    node.analysis_settings = new Dictionary<string, object>();
                }
                node.analysis_settings[name] = item.GetVarValue(index);
            }
            if (name == "DataEntry")
            {
                node.data_entry = Convert.ToString(item.GetVarValue(index));
            }
            if (name == "TimeStamp")
            {
                node.timestamp = Convert.ToString(item.GetVarValue(index));
            }
            if (name == "Data")
            {
                object value = item.GetVarValue(index);
                node.data_source = "Data property";
                var array = value as Array;
                if (array != null)
                {
                    node.dimensions = new int[array.Rank];
                    for (int dimension = 0; dimension < array.Rank; ++dimension)
                    {
                        node.dimensions[dimension] = array.GetLength(dimension);
                    }
                    if (array.Length <= 4096)
                    {
                        var values = new List<object>();
                        foreach (object entry in array)
                        {
                            values.Add(entry is ValueType || entry is string ? entry : "unsupported");
                        }
                        node.data = values.ToArray();
                    }
                }
                else if (value is ValueType || value is string)
                {
                    node.data = value;
                }
            }
        }
        // Some PartParam objects expose only their expression, without a Data
        // property. Read the documented evaluated value through IDispatch.
        if (node.data == null && path.Contains("/ParamSet/") &&
            node.methods.Contains("GetValue()"))
        {
            try
            {
                object value = item.GetType().InvokeMember("GetValue",
                    System.Reflection.BindingFlags.InvokeMethod, null, item, new object[0]);
                var array = value as Array;
                if (array != null && array.Length <= 4096)
                {
                    node.dimensions = new int[array.Rank];
                    for (int dimension = 0; dimension < array.Rank; ++dimension)
                    {
                        node.dimensions[dimension] = array.GetLength(dimension);
                    }
                    var entries = new List<object>();
                    foreach (object entry in array)
                    {
                        entries.Add(entry is ValueType || entry is string ? entry : "unsupported");
                    }
                    node.data = entries.ToArray();
                }
                else if (value is ValueType || value is string)
                {
                    node.data = value;
                }
                node.data_source = "GetValue method";
            }
            catch (Exception error)
            {
                node.evaluation_error = error.GetBaseException().Message;
            }
        }
        nodes.Add(node);
        if (depth == 0)
        {
            return;
        }
        for (int index = 0; index < item.GetItemCount(); ++index)
        {
            var child = item.GetItemByIndex(index);
            try
            {
                Visit(child, path + "/" + child.GetName(), depth - 1, nodes);
            }
            finally
            {
                Marshal.ReleaseComObject(child);
            }
        }
    }


    public static object Active;
    public static GENESYS.Application App;
    public static GENESYS.IManager Manager;
    public static GENESYS.Workspace Workspace;
    public static int Index;
    public static string[] Names(){
        var names=new List<string>();
        for(int i=0;i<Manager.GetWorkspaceCount();i++){var w=Manager.GetWorkspaceByIndex(i);names.Add(((GENESYS.IItem)w).GetName());Marshal.ReleaseComObject(w);}
        return names.ToArray();
    }
    public static void Bind(bool allowOpen,string path){
        path=System.IO.Path.GetFullPath(path);
        Console.WriteLine("NATIVE_OPEN_PATH="+path);
        Active=Marshal.GetActiveObject("Genesys.Application");App=(GENESYS.Application)Active;Manager=App.Manager;
        Console.WriteLine("WORKSPACES="+String.Join(" | ",Names()));
        foreach(string name in Names())if(name!="RFModel_AttenuatorNoise" && name!="RFModel_AMPM_A01" && !(allowOpen && name=="Blank"))throw new InvalidOperationException("Unrelated workspace; no action");
        bool found=Array.IndexOf(Names(),"RFModel_AMPM_A01")>=0;
        if(!found && allowOpen){
            if(Manager.GetWorkspaceCount()>1)throw new InvalidOperationException("Ambiguous pre-open workspace");
            Console.WriteLine(DateTime.UtcNow.ToString("o")+" BEGIN official OpenWorkspace");
            App.RunScript("Call OpenWorkspace(\""+path.Replace("\"","\"\"")+"\")",GENESYS.ScriptLanguage.genLangVBScript);
            Console.WriteLine(DateTime.UtcNow.ToString("o")+" OK official OpenWorkspace");
        }
        int matches=0;
        for(int i=0;i<Manager.GetWorkspaceCount();i++){
            var w=Manager.GetWorkspaceByIndex(i);
            if(((GENESYS.IItem)w).GetName()=="RFModel_AMPM_A01"){Workspace=w;Index=i;matches++;}
            else Marshal.ReleaseComObject(w);
        }
        if(matches!=1)throw new InvalidOperationException("Target workspace missing or ambiguous");
        CheckDone();
    }
    public static void CheckDone(){
        int done=Convert.ToInt32(Workspace.GetType().InvokeMember("IsAnalysisDone",System.Reflection.BindingFlags.InvokeMethod,null,Workspace,new object[0]));
        if(done!=1)throw new InvalidOperationException("Analysis incomplete");
        string e=Manager.GetErrors();if(!String.IsNullOrWhiteSpace(e))throw new InvalidOperationException(e);
    }
    public static Node[] Read(){
        var list=new List<Node>();
        foreach(string path in new[]{"DataPoints/Sch2/PartList/RFAmp/ParamSet","DataPoints/Sch2/PartList/Source/ParamSet",
          "DataPoints/System2","DataPoints/EqsInp","DataPoints/System2_Sch2_Data","DataPoints/System2_Data_Folder",
          "PointDerivative/Sch1/PartList/RFAmp/ParamSet","PointDerivative/Sch1/PartList/Source/ParamSet",
          "PointDerivative/System1","PointDerivative/System1_Data","PointDerivative/System1_Data_Folder","WorkspaceVariables"}){
            GENESYS.IItem current=(GENESYS.IItem)Workspace;bool owned=false;
            try{
                foreach(string part in path.Split('/')){var next=current.GetItemByName(part);if(owned)Marshal.ReleaseComObject(current);current=next;owned=true;}
                Visit(current,"RFModel_AMPM_A01/"+path,path.EndsWith("Data_Folder")?4:path.EndsWith("ParamSet")?1:3,list);
            }finally{if(owned)Marshal.ReleaseComObject(current);}
        }
        return list.ToArray();
    }
    public static void RequireDirectory(string expected) {
        if(Manager.GetWorkspaceCount()!=1)throw new InvalidOperationException("Ambiguous workspace count");
        var actual=Convert.ToString(Workspace.GetType().InvokeMember("GetWorkspaceFileDir",System.Reflection.BindingFlags.InvokeMethod,null,Workspace,new object[0]));
        if(!System.IO.Path.GetFullPath(actual).TrimEnd('\\').Equals(System.IO.Path.GetFullPath(expected).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Unexpected workspace directory: "+actual);
    }
    public static void Run() {
        var pd=((GENESYS.IItem)Workspace).GetItemByName("PointDerivative");
        var analysis=pd.GetItemByName("System1");
        try { analysis.GetType().InvokeMember("RunAnalysis",System.Reflection.BindingFlags.InvokeMethod,null,analysis,new object[0]); }
        finally {Marshal.ReleaseComObject(analysis);Marshal.ReleaseComObject(pd);}
    }
    public static void ArchiveClose(string path) {
        if(System.IO.File.Exists(path))throw new InvalidOperationException("Archive already exists");
        Workspace.GetType().InvokeMember("SaveAs",System.Reflection.BindingFlags.InvokeMethod,null,Workspace,new object[]{path});
        if(!System.IO.File.Exists(path))throw new InvalidOperationException("Archive missing");
        Workspace.GetType().InvokeMember("CloseWorkspace",System.Reflection.BindingFlags.InvokeMethod,null,Workspace,new object[0]);
        if(Manager.GetWorkspaceCount()!=0)throw new InvalidOperationException("Workspace still open");
    }
    public static string Script(string body){
        string script="Dim wsdoc\r\nSet wsdoc=Application.Manager.GetWorkspaceByIndex("+Index+")\r\n"+body;
        App.RunScript(script,GENESYS.ScriptLanguage.genLangVBScript);return script;
    }
}

